-- schema.sql — booking tables for PostgreSQL. Generated by `python manage.py schema`;
-- the app also creates any missing table on start (booking_db.init_db).

CREATE TABLE astrologers (
	id SERIAL NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	age SMALLINT NOT NULL, 
	phone_e164 VARCHAR(20) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	fee_inr INTEGER NOT NULL, 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	bio TEXT, 
	languages VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_astrologers_age CHECK (age BETWEEN 18 AND 120), 
	CONSTRAINT ck_astrologers_fee CHECK (fee_inr >= 0)
);

CREATE TABLE availability (
	id SERIAL NOT NULL, 
	astrologer_id INTEGER NOT NULL, 
	weekday SMALLINT NOT NULL, 
	start_min SMALLINT NOT NULL, 
	end_min SMALLINT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_availability_weekday CHECK (weekday BETWEEN 0 AND 6), 
	CONSTRAINT ck_availability_range CHECK (start_min >= 0 AND end_min <= 1440 AND start_min < end_min), 
	FOREIGN KEY(astrologer_id) REFERENCES astrologers (id) ON DELETE CASCADE
);

CREATE TABLE availability_blocks (
	id SERIAL NOT NULL, 
	astrologer_id INTEGER NOT NULL, 
	start_utc TIMESTAMP WITH TIME ZONE NOT NULL, 
	end_utc TIMESTAMP WITH TIME ZONE NOT NULL, 
	reason VARCHAR(120), 
	PRIMARY KEY (id), 
	CONSTRAINT ck_blocks_range CHECK (start_utc < end_utc), 
	FOREIGN KEY(astrologer_id) REFERENCES astrologers (id) ON DELETE CASCADE
);

CREATE TABLE bookings (
	id VARCHAR(36) NOT NULL, 
	astrologer_id INTEGER NOT NULL, 
	slot_start_utc TIMESTAMP WITH TIME ZONE NOT NULL, 
	slot_end_utc TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	user_name VARCHAR(80) NOT NULL, 
	user_email VARCHAR(254) NOT NULL, 
	user_whatsapp VARCHAR(20) NOT NULL, 
	questions JSON NOT NULL, 
	horoscope_input JSON NOT NULL, 
	lang VARCHAR(4) NOT NULL, 
	cancel_token_hash VARCHAR(64) NOT NULL, 
	idempotency_key VARCHAR(64), 
	consent_share_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	consent_messages_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	adult_confirmed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	notification_status JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	cancelled_at TIMESTAMP WITH TIME ZONE, 
	cancelled_by VARCHAR(12), 
	purged_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_bookings_status CHECK (status IN ('confirmed', 'cancelled')), 
	FOREIGN KEY(astrologer_id) REFERENCES astrologers (id), 
	UNIQUE (idempotency_key)
);

CREATE TABLE outbox (
	id SERIAL NOT NULL, 
	booking_id VARCHAR(36) NOT NULL, 
	event VARCHAR(20) NOT NULL, 
	channel VARCHAR(12) NOT NULL, 
	recipient VARCHAR(12) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	attempts SMALLINT DEFAULT 0 NOT NULL, 
	next_attempt_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_error VARCHAR(300), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	sent_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id) ON DELETE CASCADE
);

CREATE INDEX ix_availability_astrologer ON availability (astrologer_id);

CREATE INDEX ix_blocks_astrologer ON availability_blocks (astrologer_id, start_utc);

CREATE INDEX ix_bookings_slot ON bookings (slot_start_utc);

CREATE UNIQUE INDEX uq_bookings_confirmed_slot ON bookings (astrologer_id, slot_start_utc) WHERE status = 'confirmed';

CREATE INDEX ix_outbox_due ON outbox (status, next_attempt_at);
